            w_norm=np.linalg.norm(w)
            if w_norm==0:
                return np.float64(0.0), v
            v_next=w/w_norm
            if np.abs(new_eig-eigenvalue)<tol:
                eigenvalue=new_eig
                v=v_next
                break
            eigenvalue=new_eig
            v=v_next
